#include <iostream>
#include <string>
using namespace std;

string render(string tmpl, string key, string val) {
    string ph = "{{" + key + "}}";
    size_t pos = tmpl.find(ph);
    if (pos != string::npos) {
        return tmpl.substr(0, pos) + val + tmpl.substr(pos + ph.length());
    }
    return tmpl;
}

int main() {
    cout << render("Hello, {{name}}!", "name", "World") << endl;
    return 0;
}
